set -e
TS=1784215000
ROOT=/home/ubuntu/testlogon
cd $ROOT
# --- backups ---
for f in app/routers/alerts.py app/services/creator_earnings.py app/main.py; do
  cp $f $f.bak_tipx_$TS
done
echo BACKED_UP
# --- write the two NEW files ---
echo '' | base64 -d > app/services/tips_measurement.py
echo '' | base64 -d > app/routers/tips_measurement.py
python3 -c "import ast; ast.parse(open('app/services/tips_measurement.py').read()); ast.parse(open('app/routers/tips_measurement.py').read()); print('NEWFILES_AST_OK')"
# --- content-anchored edits ---
python3 - <<'PYEOF'
# 1) main.py: register import + include
p='app/main.py'; s=open(p).read()
imp='from app.routers.tip_leaderboard import internal_router as tip_leaderboard_internal_router'
if 'tips_measurement' not in s:
    s=s.replace(imp, imp+'\nfrom app.routers.tips_measurement import router as tips_measurement_router')
    inc='    app.include_router(tip_leaderboard_internal_router)'
    s=s.replace(inc, inc+'\n    app.include_router(tips_measurement_router)  # TIPX-D measurement', 1)
    open(p,'w').write(s); print('MAIN_PATCHED')
else: print('MAIN_ALREADY')

# 2) creator_earnings.py: wire pending_payout (D5)
p='app/services/creator_earnings.py'; s=open(p).read()
old='''    return {
        "today_cents": today_cents,
        "this_week_cents": week_cents,
        "this_month_cents": month_cents,
        "all_time_cents": all_time_cents,
        "currency": "USD",
        "pending_payout_cents": 0,  # populated after MON-004
    }'''
new='''    # TIPX-D5: wire the real in-flight payout figure (MON-004 is live via
    # creator_payouts.get_available_balance -> pending_cents = requested/approved/
    # processing payouts not yet debited). Best-effort: any failure falls back to 0
    # so the earnings quick-stats never breaks on a payout-service hiccup.
    pending_payout_cents = 0
    try:
        from app.services.creator_payouts import get_available_balance

        pending_payout_cents = int(get_available_balance(user_id).get("pending_cents", 0))
    except Exception:  # pragma: no cover - defensive
        logger.warning("quick_stats_pending_payout_lookup_failed", exc_info=True)

    return {
        "today_cents": today_cents,
        "this_week_cents": week_cents,
        "this_month_cents": month_cents,
        "all_time_cents": all_time_cents,
        "currency": "USD",
        "pending_payout_cents": pending_payout_cents,  # TIPX-D5 (MON-004 wired)
    }'''
if 'TIPX-D5' not in s:
    assert old in s, 'CE anchor missing'
    s=s.replace(old,new); open(p,'w').write(s); print('CE_PATCHED')
else: print('CE_ALREADY')

# 3) alerts.py: replace get_tips_summary body with ledger-backed version
p='app/routers/alerts.py'; s=open(p).read()
start='@router.get("/alerts/tips-summary")'
endm='@router.post("/alerts/mark-group-read")'
if 'get_tips_received_summary' not in s:
    i=s.index(start); j=s.index(endm, i)
    newfn='''@router.get("/alerts/tips-summary")
async def get_tips_summary(
    period: str = Query(default="30d"),
    ctx: Dict[str, str] = Depends(require_ui_session),
):
    """Ledger-backed tips-received summary for the current user (TIPX-D1).

    Retires the old alert-stream total (GROSS, post_tip+message_tip only, capped
    at the last 1000 alerts, mislabeled "Total Earned"). This now reads the
    billing LEDGER via tips_measurement so total_tips_cents is NET, covers all 8
    tip surfaces, excludes reversed tips, and RECONCILES to the earnings tips
    bucket and the leaderboard for the same creator/period.
    """
    from app.services.tips_measurement import get_tips_received_summary

    user_sub = ctx["user_sub"]
    if period not in ("7d", "30d", "all"):
        period = "30d"

    summary = get_tips_received_summary(user_sub, period)
    by_surface = summary.get("by_type", {})
    legacy_by_type = {
        "post_tip": by_surface.get("post", {"count": 0, "total_cents": 0}),
        "message_tip": by_surface.get("message", {"count": 0, "total_cents": 0}),
    }
    return {
        "total_tips_cents": summary.get("total_net_cents", 0),
        "tip_count": summary.get("tip_count", 0),
        "top_tippers": summary.get("top_tippers", []),
        "by_type": legacy_by_type,
        "by_surface": by_surface,
        "unique_tippers": summary.get("unique_tippers", 0),
        "net": True,
        "source": "ledger",
    }


'''
    s=s[:i]+newfn+s[j:]; open(p,'w').write(s); print('ALERTS_PATCHED')
else: print('ALERTS_ALREADY')
PYEOF
python3 -c "import ast; [ast.parse(open(f).read()) for f in ['app/main.py','app/services/creator_earnings.py','app/routers/alerts.py']]; print('EDITED_AST_OK')"
chown ubuntu:ubuntu app/services/tips_measurement.py app/routers/tips_measurement.py app/routers/alerts.py app/services/creator_earnings.py app/main.py
echo CHOWNED
sudo -u ubuntu bash /home/ubuntu/restart_backend.sh
sleep 4
echo -n 'OPENAPI_HTTP: '; curl -s -o /dev/null -w '%{http_code}\n' http://localhost:8000/openapi.json
echo -n 'TIPS_RECEIVED_ROUTE: '; curl -s http://localhost:8000/openapi.json | python3 -c "import sys,json; d=json.load(sys.stdin); print([p for p in d['paths'] if 'tips/received' in p or 'tips/sent' in p])"
